module ietf-netconf {
  namespace "urn:ietf:params:xml:ns:netconf:base:1.0";
  prefix nc;

  organization
    "IETF NETCONF (Network Configuration) Working Group";
  contact
    "WG Web:   <http://tools.ietf.org/wg/netconf/>
     WG List:  <netconf@ietf.org>

     WG Chair: Bert Wijnen
               <bertietf@bwijnen.net>

     WG Chair: Mehmet Ersue
               <mehmet.ersue@nsn.com>

     Editor:   Martin Bjorklund
               <mbj@tail-f.com>

     Editor:   Juergen Schoenwaelder
               <j.schoenwaelder@jacobs-university.de>

     Editor:   Andy Bierman
               <andy.bierman@brocade.com>";
  description
    "NETCONF Protocol Data Types and Protocol Operations.

     Copyright (c) 2011 IETF Trust and the persons identified as
     the document authors.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (http://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 6241; see
     the RFC itself for full legal notices.";

  revision 2011-06-01;

  ietf-yang-metadata:annotation "operation" {
    type enumeration {
      enum "merge" {
        value 0;
        status current;
      }
      enum "replace" {
        value 1;
        status current;
      }
      enum "create" {
        value 2;
        status current;
      }
      enum "delete" {
        value 3;
        status current;
      }
      enum "remove" {
        value 4;
        status current;
      }
    }
  }
  ietf-yang-metadata:annotation "type" {
    type enumeration {
      enum "subtree" {
        value 0;
        status current;
      }
      enum "xpath" {
        value 1;
        status current;
      }
    }
  }
  ietf-yang-metadata:annotation "select" {
    type string;
  }

  container rpc-error {
    presence "true";
    config true;
    status current;
    leaf error-type {
      type enumeration {
        enum "transport" {
          value 0;
          status current;
        }
        enum "rpc" {
          value 1;
          status current;
        }
        enum "protocol" {
          value 2;
          status current;
        }
        enum "application" {
          value 3;
          status current;
        }
      }
      config true;
      status current;
    }
    leaf error-tag {
      type enumeration {
        enum "in-use" {
          value 0;
          status current;
        }
        enum "invalid-value" {
          value 1;
          status current;
        }
        enum "too-big" {
          value 2;
          status current;
        }
        enum "missing-attribute" {
          value 3;
          status current;
        }
        enum "bad-attribute" {
          value 4;
          status current;
        }
        enum "unknown-attribute" {
          value 5;
          status current;
        }
        enum "missing-element" {
          value 6;
          status current;
        }
        enum "bad-element" {
          value 7;
          status current;
        }
        enum "unknown-element" {
          value 8;
          status current;
        }
        enum "unknown-namespace" {
          value 9;
          status current;
        }
        enum "access-denied" {
          value 10;
          status current;
        }
        enum "lock-denied" {
          value 11;
          status current;
        }
        enum "resource-denied" {
          value 12;
          status current;
        }
        enum "rollback-failed" {
          value 13;
          status current;
        }
        enum "data-exists" {
          value 14;
          status current;
        }
        enum "data-missing" {
          value 15;
          status current;
        }
        enum "operation-not-supported" {
          value 16;
          status current;
        }
        enum "operation-failed" {
          value 17;
          status current;
        }
        enum "partial-operation" {
          value 18;
          status current;
        }
        enum "malformed-message" {
          value 19;
          status current;
        }
      }
      config true;
      status current;
    }
    leaf error-severity {
      type enumeration {
        enum "error" {
          value 0;
          status current;
        }
        enum "warning" {
          value 1;
          status current;
        }
      }
      config true;
      status current;
    }
    leaf error-app-tag {
      type string;
      config true;
      status current;
    }
    leaf error-path {
      type string;
      config true;
      status current;
    }
  }

  rpc get-config {
    status current;
    description
      "Retrieve all or part of a specified configuration.";
    reference
      "RFC 6241, Section 7.1";

    input {
      container source {
        status current;
        description
          "Particular configuration to retrieve.";
        choice config-source {
          mandatory true;
          status current;
          description
            "The configuration to retrieve.";
          case candidate {
            status current;
          }
          case running {
            status current;
            leaf running {
              type empty;
              status current;
              description
                "The running configuration is the config source.";
            }
          }
          case startup {
            status current;
          }
        }
      }
      anyxml filter {
        ietf-netconf:get-filter-element-attributes;
        status current;
        description
          "Subtree or XPath filter to use.";
      }
      leaf with-defaults {
        type enumeration {
          enum "report-all" {
            value 0;
            status current;
            description
              "All default data is reported.";
            reference
              "RFC 6243; Section 3.1";
          }
          enum "report-all-tagged" {
            value 1;
            status current;
            description
              "All default data is reported.
               Any nodes considered to be default data
               will contain a 'default' XML attribute,
               set to 'true' or '1'.";
            reference
              "RFC 6243; Section 3.4";
          }
          enum "trim" {
            value 2;
            status current;
            description
              "Values are not reported if they contain the default.";
            reference
              "RFC 6243; Section 3.2";
          }
          enum "explicit" {
            value 3;
            status current;
            description
              "Report values that contain the definition of
               explicitly set data.";
            reference
              "RFC 6243; Section 3.3";
          }
        }
        status current;
        description
          "The explicit defaults processing mode requested.";
        reference
          "RFC 6243; Section 4.5.1";
      }
    }

    output {
      anyxml data {
        status current;
        description
          "Copy of the source datastore subset that matched
           the filter criteria (if any).  An empty data container
           indicates that the request did not produce any results.";
      }
    }
  }
  rpc edit-config {
    status current;
    description
      "The <edit-config> operation loads all or part of a specified
       configuration to the specified target configuration.";
    reference
      "RFC 6241, Section 7.2";

    input {
      container target {
        status current;
        description
          "Particular configuration to edit.";
        choice config-target {
          mandatory true;
          status current;
          description
            "The configuration target.";
          case candidate {
            status current;
          }
          case running {
            status current;
          }
        }
      }
      leaf default-operation {
        type enumeration {
          enum "merge" {
            value 0;
            status current;
            description
              "The default operation is merge.";
          }
          enum "replace" {
            value 1;
            status current;
            description
              "The default operation is replace.";
          }
          enum "none" {
            value 2;
            status current;
            description
              "There is no default operation.";
          }
        }
        default "merge";
        status current;
        description
          "The default operation to use.";
      }
      leaf error-option {
        type enumeration {
          enum "stop-on-error" {
            value 0;
            status current;
            description
              "The server will stop on errors.";
          }
          enum "continue-on-error" {
            value 1;
            status current;
            description
              "The server may continue on errors.";
          }
          enum "rollback-on-error" {
            value 2;
            status current;
            description
              "The server will roll back on errors.
               This value can only be used if the 'rollback-on-error'
               feature is supported.";
          }
        }
        default "stop-on-error";
        status current;
        description
          "The error option to use.";
      }
      choice edit-content {
        mandatory true;
        status current;
        description
          "The content for the edit operation.";
        case config {
          status current;
          anyxml config {
            status current;
            description
              "Inline Config content.";
          }
        }
        case url {
          status current;
        }
      }
    }
  }
  rpc copy-config {
    status current;
    description
      "Create or replace an entire configuration datastore with the
       contents of another complete configuration datastore.";
    reference
      "RFC 6241, Section 7.3";

    input {
      container target {
        status current;
        description
          "Particular configuration to copy to.";
        choice config-target {
          mandatory true;
          status current;
          description
            "The configuration target of the copy operation.";
          case candidate {
            status current;
          }
          case running {
            status current;
          }
          case startup {
            status current;
          }
          case url {
            status current;
          }
        }
      }
      container source {
        status current;
        description
          "Particular configuration to copy from.";
        choice config-source {
          mandatory true;
          status current;
          description
            "The configuration source for the copy operation.";
          case candidate {
            status current;
          }
          case running {
            status current;
            leaf running {
              type empty;
              status current;
              description
                "The running configuration is the config source.";
            }
          }
          case startup {
            status current;
          }
          case url {
            status current;
          }
          case config {
            status current;
            anyxml config {
              status current;
              description
                "Inline Config content: <config> element.  Represents
                 an entire configuration datastore, not
                 a subset of the running datastore.";
            }
          }
        }
      }
      leaf with-defaults {
        type enumeration {
          enum "report-all" {
            value 0;
            status current;
            description
              "All default data is reported.";
            reference
              "RFC 6243; Section 3.1";
          }
          enum "report-all-tagged" {
            value 1;
            status current;
            description
              "All default data is reported.
               Any nodes considered to be default data
               will contain a 'default' XML attribute,
               set to 'true' or '1'.";
            reference
              "RFC 6243; Section 3.4";
          }
          enum "trim" {
            value 2;
            status current;
            description
              "Values are not reported if they contain the default.";
            reference
              "RFC 6243; Section 3.2";
          }
          enum "explicit" {
            value 3;
            status current;
            description
              "Report values that contain the definition of
               explicitly set data.";
            reference
              "RFC 6243; Section 3.3";
          }
        }
        status current;
        description
          "The explicit defaults processing mode requested.";
        reference
          "RFC 6243; Section 4.5.1";
      }
    }
  }
  rpc delete-config {
    status current;
    description
      "Delete a configuration datastore.";
    reference
      "RFC 6241, Section 7.4";

    input {
      container target {
        status current;
        description
          "Particular configuration to delete.";
        choice config-target {
          mandatory true;
          status current;
          description
            "The configuration target to delete.";
          case startup {
            status current;
          }
          case url {
            status current;
          }
        }
      }
    }
  }
  rpc lock {
    status current;
    description
      "The lock operation allows the client to lock the configuration
       system of a device.";
    reference
      "RFC 6241, Section 7.5";

    input {
      container target {
        status current;
        description
          "Particular configuration to lock.";
        choice config-target {
          mandatory true;
          status current;
          description
            "The configuration target to lock.";
          case candidate {
            status current;
          }
          case running {
            status current;
            leaf running {
              type empty;
              status current;
              description
                "The running configuration is the config target.";
            }
          }
          case startup {
            status current;
          }
        }
      }
    }
  }
  rpc unlock {
    status current;
    description
      "The unlock operation is used to release a configuration lock,
       previously obtained with the 'lock' operation.";
    reference
      "RFC 6241, Section 7.6";

    input {
      container target {
        status current;
        description
          "Particular configuration to unlock.";
        choice config-target {
          mandatory true;
          status current;
          description
            "The configuration target to unlock.";
          case candidate {
            status current;
          }
          case running {
            status current;
            leaf running {
              type empty;
              status current;
              description
                "The running configuration is the config target.";
            }
          }
          case startup {
            status current;
          }
        }
      }
    }
  }
  rpc get {
    status current;
    description
      "Retrieve running configuration and device state information.";
    reference
      "RFC 6241, Section 7.7";

    input {
      anyxml filter {
        ietf-netconf:get-filter-element-attributes;
        status current;
        description
          "This parameter specifies the portion of the system
           configuration and state data to retrieve.";
      }
      leaf with-defaults {
        type enumeration {
          enum "report-all" {
            value 0;
            status current;
            description
              "All default data is reported.";
            reference
              "RFC 6243; Section 3.1";
          }
          enum "report-all-tagged" {
            value 1;
            status current;
            description
              "All default data is reported.
               Any nodes considered to be default data
               will contain a 'default' XML attribute,
               set to 'true' or '1'.";
            reference
              "RFC 6243; Section 3.4";
          }
          enum "trim" {
            value 2;
            status current;
            description
              "Values are not reported if they contain the default.";
            reference
              "RFC 6243; Section 3.2";
          }
          enum "explicit" {
            value 3;
            status current;
            description
              "Report values that contain the definition of
               explicitly set data.";
            reference
              "RFC 6243; Section 3.3";
          }
        }
        status current;
        description
          "The explicit defaults processing mode requested.";
        reference
          "RFC 6243; Section 4.5.1";
      }
    }

    output {
      anyxml data {
        status current;
        description
          "Copy of the running datastore subset and/or state
           data that matched the filter criteria (if any).
           An empty data container indicates that the request did not
           produce any results.";
      }
    }
  }
  rpc close-session {
    status current;
    description
      "Request graceful termination of a NETCONF session.";
    reference
      "RFC 6241, Section 7.8";
  }
  rpc kill-session {
    status current;
    description
      "Force the termination of a NETCONF session.";
    reference
      "RFC 6241, Section 7.9";

    input {
      leaf session-id {
        type uint32 {
          range "1..4294967295";
        }
        mandatory true;
        status current;
        description
          "Particular session to kill.";
      }
    }
  }
}

module ietf-netconf-with-defaults {
  namespace "urn:ietf:params:xml:ns:yang:ietf-netconf-with-defaults";
  prefix ncwd;

  organization
    "IETF NETCONF (Network Configuration Protocol) Working Group";
  contact
    "WG Web:   <http://tools.ietf.org/wg/netconf/>

     WG List:  <netconf@ietf.org>

     WG Chair: Bert Wijnen
               <bertietf@bwijnen.net>

     WG Chair: Mehmet Ersue
               <mehmet.ersue@nsn.com>

     Editor: Andy Bierman
             <andy.bierman@brocade.com>

     Editor: Balazs Lengyel
             <balazs.lengyel@ericsson.com>";
  description
    "This module defines an extension to the NETCONF protocol
     that allows the NETCONF client to control how default
     values are handled by the server in particular NETCONF
     operations.

